theory.example:
#include <string>
#include <utility>

std::string mutable_name = "Ada";
std::string moved(std::move(mutable_name));
// moved == "Ada"; mutable_name остаётся допустимым объектом,
// но не следует предполагать конкретное значение после перемещения.

const std::string fixed = "Grace";
std::string copied(std::move(fixed));
// std::move(fixed) имеет тип const std::string&&;
// используется конструктор копирования, а не std::string(string&&).

references.example:
#include <utility>
int count = 4;
int&& view = std::move(count);
int& alias = view;
// alias и view обозначают тот же объект count.
// Для выбора перегрузки отдельно проверь категорию каждого выражения.

#include <type_traits>
struct Buffer {
  Buffer(const Buffer&);
  Buffer(Buffer&&) noexcept;
};
static_assert(std::is_nothrow_move_constructible_v<Buffer>);
// Это свойство известно на этапе компиляции; его не измеряют запуском кода.
